using System;using System.Linq;using System.Reflection;using System.Threading.Tasks;using UnityEngine;using AntColony.Core;using AntColony.Units;using AntColony.Buildings;using AntColony.Data;using AntColony.UI;
public static class Dining1114Contact {public static async Task<string> Run(){var actors=CommanderRoster.Instance.Commanders.Where(c=>c&&c.IsEating&&c.MealTable).ToArray();if(actors.Length<3)throw new Exception("At least three seated actors required");var c=actors[0];var table=c.MealTable;var p=c.GetComponent<MeshyNativeMotionPlayer>();var bones=p.NativeModel.GetComponentsInChildren<Transform>();var hand=bones.Single(t=>t.name=="mixamorig:RightHand");var head=bones.Single(t=>t.name=="mixamorig:Head");var left=bones.Single(t=>t.name=="mixamorig:LeftHand");var mid=bones.Single(t=>t.name=="mixamorig:LeftHandMiddle1");Vector3 start=hand.position;float movement=0,gap=99,bowlError=0;SimulationPause.UserSpeed(1);for(int i=0;i<32;i++){await Task.Delay(100);movement=Mathf.Max(movement,Vector3.Distance(start,hand.position));gap=Mathf.Min(gap,Vector3.Distance(head.position,hand.position));var bowl=c.GetComponentsInChildren<Transform>().FirstOrDefault(t=>t.name=="Meal bowl grip"&&t.gameObject.activeInHierarchy);if(!bowl)throw new Exception("Bowl missing");bowlError=Mathf.Max(bowlError,Vector3.Distance(bowl.position,Vector3.Lerp(left.position,mid.position,.65f)));}SimulationPause.UserSpeed(0);if(movement<.08f||bowlError>.025f)throw new Exception("Hand or bowl failed");
 var pc=UnityEngine.Object.FindAnyObjectByType<BuildingPlacementController>();pc.BeginPlacement(BuildingKind.BigTable,UnitRole.Worker,null);bool overlapsAllowed=(bool)typeof(BuildingPlacementController).GetMethod("CellValid",BindingFlags.NonPublic|BindingFlags.Instance).Invoke(pc,new object[]{table.Position});pc.CancelPlacement();if(overlapsAllowed)throw new Exception("Overlapping table placement allowed");
 var text="PASS hand cycle travel="+movement+" wrist/head minimum="+gap+" bowl/palm offset="+bowlError+"; overlapping furniture placement rejected";System.IO.File.WriteAllText("work/furniture-wall-1114/dining-contact.txt",text);ScreenCapture.CaptureScreenshot("work/furniture-wall-1114/dining-hands.png");await Task.Delay(300);return text;}}
